70	func resolvePlugin(rootCmd *cobra.Command, args []string) (binPath string, pluginArgs []string, ok bool) {
71		if len(args) == 0 {
72			return "", nil, false
73		}
74		name := args[0]
75		if !isPluginCandidate(name) {
76			return "", nil, false
77		}
78		// Built-in commands always win.
79		if cmd, _, err := rootCmd.Find(args); err == nil && cmd != rootCmd {
80			return "", nil, false
81		}
82		binName := pluginBinaryPrefix + name
83		binPath, err := exec.LookPath(binName)
84		if err != nil {
85			// LookPath conflates "not on PATH" with "found but not executable".
86			// Distinguish: if a file with this name exists on PATH but isn't
87			// executable, surface that as a launch error rather than falling
88			// through to Cobra's generic unknown-command path.
89			if p, found := findInaccessiblePlugin(binName); found {
90				return p, args[1:], true
91			}
92			return "", nil, false
93		}
94		if isAgentProtocolBinary(binPath) {
95			return "", nil, false
96		}
97		return binPath, args[1:], true
98	}
99	
100	// findInaccessiblePlugin scans PATH for a non-directory file with the
101	// given name. Only meaningful after exec.LookPath has already failed —
102	// indicates the file exists but lacks the executable bit (or the
103	// equivalent platform-specific accessibility).
104	func findInaccessiblePlugin(filename string) (string, bool) {
105		for _, dir := range filepath.SplitList(os.Getenv("PATH")) {
106			if dir == "" {
107				continue
108			}
109			candidate := filepath.Join(dir, filename)
110			info, err := os.Stat(candidate) //nolint:gosec // PATH entries are user-trusted; scanning them is the point.
111			if err != nil || info.IsDir() {
112				continue
113			}
114			return candidate, true
115		}
116		return "", false
117	}
118	
119	func isPluginCandidate(name string) bool {
120		if name == "" {
121			return false
122		}
123		if strings.HasPrefix(name, "-") {
124			return false
125		}
126		// `agent-*` is reserved for the external agent protocol.
127		if strings.HasPrefix(name, "agent-") {
128			return false
129		}
130		if strings.ContainsAny(name, `/\`) {
131			return false
132		}
133		return true
134	}
135	
136	// isAgentProtocolBinary returns true when the binary name is reserved for
137	// the external agent protocol. Strip Windows extensions first so
138	// `entire-agent-foo.exe` is also recognized.
139	func isAgentProtocolBinary(binPath string) bool {
140		base := external.StripExeExt(filepath.Base(binPath))
141		return strings.HasPrefix(base, agentPluginBinaryPrefix)
142	}
143	
144	// runPlugin executes the resolved plugin binary, propagating its exit code.
145	// On context cancellation the child gets SIGINT (with a 5s grace before the
146	// runtime falls back to SIGKILL) so plugins can clean up. Terminal signals
147	// reach the child directly via the shared process group.
148	func runPlugin(ctx context.Context, binPath string, args []string) int {
149		cmd := exec.CommandContext(ctx, binPath, args...)
150		cmd.Cancel = func() error { return cmd.Process.Signal(os.Interrupt) }
151		cmd.WaitDelay = 5 * time.Second
152		cmd.Stdin = os.Stdin
153		cmd.Stdout = os.Stdout
154		cmd.Stderr = os.Stderr
155		cmd.Env = append(os.Environ(), "ENTIRE_CLI_VERSION="+versioninfo.Version)
156		if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
157			cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
158		}
159	
160		if err := cmd.Run(); err != nil {
161			var exitErr *exec.ExitError
162			if errors.As(err, &exitErr) {
163				return exitErr.ExitCode()
164			}
165			// Prefix with the plugin name so users can tell parent vs child
166			// errors apart in mixed stderr.
167			fmt.Fprintf(os.Stderr, "Failed to run plugin %s: %v\n", filepath.Base(binPath), err)
168			return 1
169		}
170		return 0
171	}
