15	// writePluginBinary writes a shell script that records argv to argFile.
16	// Skips the calling test on Windows.
17	func writePluginBinary(t *testing.T, dir, name, argFile string, exitCode int) string {
18		t.Helper()
19		if runtime.GOOS == windowsGOOS {
20			t.Skip("plugin shell-script harness only runs on Unix")
21		}
22		path := filepath.Join(dir, name)
23		script := fmt.Sprintf("#!/bin/sh\nprintf '%%s\\n' \"$@\" > %q\nexit %d\n", argFile, exitCode)
24		if err := os.WriteFile(path, []byte(script), 0o755); err != nil {
25			t.Fatalf("write plugin %s: %v", path, err)
26		}
27		return path
28	}
